const copy={
en:{work:'The photographs',about:'Behind the gaze',index:'Index',heroEyebrow:'PHOTOGRAPHS, MEMORIES & A LITTLE PRETENSION',subtitle:'A pretentious gaze.<br>A very personal way of seeing.',explore:'Let your eyes wander',archiveLabel:'THE PHOTOGRAPHIC INDEX',archiveTitle:'Keep looking.',load:'More photographs',aboutLabel:'BEHIND THE GAZE',aboutLead:'I’m still not sure whether I love photography or cameras more.',aboutBody:'Photography runs in my family. My grandfather sent 16mm films from Brazil to his relatives in Hungary. My father always had a camera close by. At fifteen, I turned my bathroom in Salvador into a darkroom. Photography eventually led me to graphic design. The urge to look never left.',aboutEnd:'My mother taught me something else: photographs are meant to be lived with.',contact:'Say hello',bookNote:'Photographs and words adapted from Olhar Pretensioso / A Pretentious Gaze, 2021.',footerLine:'There’s already so much<br>imagery in the world.',backTop:'Back to the beginning ↑',viewerHint:'Use the arrow keys to wander. Esc to return.',all:'All photographs',count:'photographs to get lost in',view:'Explore this chapter',open:'View photograph',close:'Close photograph',prev:'Previous photograph',next:'Next photograph',skip:'Skip to photographs'},
pt:{work:'As fotografias',about:'Por trás do olhar',index:'Índice',heroEyebrow:'FOTOGRAFIAS, MEMÓRIAS E UM POUCO DE PRETENSÃO',subtitle:'Um olhar pretensioso.<br>Um jeito muito pessoal de ver.',explore:'Deixe o olhar passear',archiveLabel:'ÍNDICE FOTOGRÁFICO',archiveTitle:'Continue olhando.',load:'Mais fotografias',aboutLabel:'POR TRÁS DO OLHAR',aboutLead:'Ainda tenho dúvidas se gosto mais de fotografia ou das câmeras.',aboutBody:'Fotografia é coisa de família. Meu avô enviava filmes de 16mm do Brasil para os parentes na Hungria. Meu pai sempre tinha uma câmera por perto. Aos quinze anos, transformei meu banheiro em Salvador num laboratório. A fotografia acabou me levando ao design gráfico. A vontade de olhar ficou.',aboutEnd:'Minha mãe me ensinou outra coisa: fotografia é para fazer parte da vida.',contact:'Vamos conversar',bookNote:'Fotografias e textos adaptados de Olhar Pretensioso / A Pretentious Gaze, 2021.',footerLine:'Já tem muita<br>imagem no mundo.',backTop:'Voltar ao começo ↑',viewerHint:'Use as setas para passear. Esc para voltar.',all:'Todas as fotografias',count:'fotografias para se perder',view:'Explore este capítulo',open:'Ver fotografia',close:'Fechar fotografia',prev:'Fotografia anterior',next:'Próxima fotografia',skip:'Ir para as fotografias'}};

Object.assign(copy.en,{
  "historyLabel": "A FAMILY WAY OF SEEING",
  "historyTitle": "Before my gaze",
  "historyLead": "My grandfather, my father, my uncles. Photography was part of our family long before I began making pictures of my own.",
  "grandfatherTitle": "Jorge. Images across an ocean.",
  "grandfatherBody": "My grandfather Jorge Kertész arrived in Brazil from Hungary in 1935. His country, language and family were a long sea voyage away. On carefully chosen days, he gathered his wife and children to film them in 16mm. The developed films went back to Hungary by ship: a way of introducing his Brazilian family to the relatives he had left behind.",
  "fatherTitle": "Mário, Carlos and Eduardo.",
  "fatherBody": "I have countless memories of my father with a camera in his hand. He tells me about the photographic adventures he shared with his brothers, Carlos and Eduardo. As young men, they took photographs and made the prints by hand, turning them into postcards to sell to local businesses. Long before my own photographs, there were theirs.",
  "ownTitle": "A camera. A bathroom. A beginning.",
  "ownBody": "My father gave me my first camera, a Kodak Instamatic 11. By fifteen, I was borrowing his Nikon and collecting black-and-white film from the newspaper he ran. Later, I turned my bathroom in my mother’s apartment in Salvador into a makeshift darkroom. I spent countless nights learning to develop negatives and make prints.",
  "ownMore": "Arlete Soares gave me my first work as a photographer and assistant. Through her I met Popó, whose hands shaped light under the enlarger, and the designer Marcos Paulo. Photography had opened the door to what would become my profession: graphic design.",
  "historyQuote": "Photographs have the strange ability to reactivate memories and make them look original.",
  "familyFilmCaption": "Mário, Eduardo and Carlos Kertész. A frame from Jorge Kertész’s 16mm films, c. 1950.",
  "brideCaption": "Bride. Eduardo Kertész, c. 1963.",
  "studentsCaption": "Students. Carlos Kertész, c. 1960.",
  "firstCameraCaption": "Receiving my first camera from my father on my birthday. Family archive.",
  "historyCredit": "Family photographs reproduced from Olhar Pretensioso, 2021. Individual credits appear with each image."
});
Object.assign(copy.pt,{
  "historyLabel": "UM OLHAR DE FAMÍLIA",
  "historyTitle": "Antes do meu olhar",
  "historyLead": "Meu avô, meu pai, meus tios. A fotografia já fazia parte da nossa família muito antes de eu começar a fazer minhas próprias imagens.",
  "grandfatherTitle": "Jorge. Imagens pelo oceano.",
  "grandfatherBody": "Meu avô Jorge Kertész chegou da Hungria ao Brasil em 1935. Seu país, sua língua e sua família estavam a uma longa viagem de navio de distância. Em dias escolhidos, reunia a mulher e os filhos para filmá-los em 16mm. Os filmes revelados seguiam de navio para a Hungria: uma maneira de apresentar sua família brasileira aos parentes que haviam ficado por lá.",
  "fatherTitle": "Mário, Carlos e Eduardo.",
  "fatherBody": "Tenho muitas lembranças do meu pai com uma câmera na mão. Ele me conta as aventuras fotográficas que viveu com os irmãos, Carlos e Eduardo. Na juventude, fotografavam e ampliavam à mão imagens em cartões-postais para vender ao comércio local. Muito antes das minhas fotografias, vieram as deles.",
  "ownTitle": "Uma câmera. Um banheiro. Um começo.",
  "ownBody": "Meu pai me deu minha primeira câmera, uma Kodak Instamatic 11. Aos quinze anos, eu já tomava sua Nikon emprestada e buscava filmes em preto e branco no jornal que ele dirigia. Depois, transformei meu banheiro no apartamento da minha mãe, em Salvador, num laboratório improvisado. Passei muitas noites em claro, aprendendo a revelar e ampliar.",
  "ownMore": "Arlete Soares me deu meu primeiro trabalho como fotógrafo e assistente. Através dela conheci Popó, cujas mãos desenhavam a luz sob o ampliador, e o designer Marcos Paulo. A fotografia abriu a porta para o que viria a ser minha profissão: o design gráfico.",
  "historyQuote": "Uma imagem registrada, capaz de reativar memórias e fazê-las parecer originais.",
  "familyFilmCaption": "Mário, Eduardo e Carlos Kertész. Fotograma dos filmes de 16mm de Jorge Kertész, c. 1950.",
  "brideCaption": "Noiva. Eduardo Kertész, c. 1963.",
  "studentsCaption": "Estudantes. Carlos Kertész, c. 1960.",
  "firstCameraCaption": "Ganhando minha primeira câmera das mãos do meu pai, no meu aniversário. Acervo de família.",
  "historyCredit": "Fotografias de família reproduzidas de Olhar Pretensioso, 2021. Créditos individuais junto às imagens."
});
const heroIds=['p169-0','p071-0','p085-0','p149-0'];
let heroIndex=0;
function renderHero(){
 const p=photos.find(p=>p.id===heroIds[heroIndex]);if(!p)return;
 const img=$('.hero-photo');img.src=asset(p);img.alt=p[language]+(p.place?' — '+p.place:'');
 img.width=p.width;img.height=p.height;
 $('.hero-caption').innerHTML=safe(p[language])+'<span>'+safe(p.place)+'</span>';
 $('.hero-index').textContent=String(heroIndex+1).padStart(2,'0')+' / 04';
 $('.hero-prev').setAttribute('aria-label',copy[language].prev);$('.hero-next').setAttribute('aria-label',copy[language].next);
 $('.hero-gallery-controls').setAttribute('aria-label',language==='pt'?'Fotografias de abertura':'Opening photographs');
 const next=new Image();next.src=asset(photos.find(p=>p.id===heroIds[(heroIndex+1)%heroIds.length]));
}
function moveHero(step){heroIndex=(heroIndex+step+heroIds.length)%heroIds.length;renderHero()}

const chapters=[
{id:'light',n:'01',en:'Light & shadow',pt:'Luz e sombra',labelEn:'THE ART OF NOTICING',labelPt:'A ARTE DE REPARAR',bodyEn:'A shadow is the sun drawing in black ink. Complex things become simple shapes. Like graphic design: saying more with less.',bodyPt:'A sombra é o sol desenhando em preto. O que é complexo vira forma simples. Como no design gráfico: falar bem com poucas palavras.',quoteEn:'The sun, drawing in black ink.',quotePt:'O sol desenhando em preto.',photos:['p052-0','p056-0','p193-0']},
{id:'city',n:'02',en:'New York, again',pt:'Nova Iorque, de novo',labelEn:'THE CITY THAT WAKES THE EYE',labelPt:'A CIDADE QUE ACORDA O OLHAR',bodyEn:'Every arrival in New York reawakened my artistic ambitions. The noise. The old beside the new. A familiar street, a different light. Each return brings something I hadn’t seen before.',bodyPt:'Bastava chegar a Nova Iorque para acordar minhas ambições artísticas. O barulho. O velho junto do novo. Uma rua conhecida, uma luz diferente. A cada volta, alguma coisa que eu ainda não tinha visto.',quoteEn:'A city that never runs out of things to see.',quotePt:'Uma cidade que não acaba de mostrar.',photos:['p069-0','p063-0','p071-0']},
{id:'elsewhere',n:'03',en:'Somewhere else',pt:'Em outro lugar',labelEn:'CURIOSITY, IN TRANSIT',labelPt:'CURIOSIDADE EM TRÂNSITO',bodyEn:'Unfamiliar places wake up the imagination. What is that life like? Who lives in that house? Traveling begins with a change of scenery. Looking begins with a question.',bodyPt:'O diferente acende a imaginação. Como será aquela vida? Quem mora naquela casa? Viajar começa com uma mudança de paisagem. Olhar começa com uma pergunta.',quoteEn:'What is that life like?',quotePt:'Como será aquela vida?',photos:['p095-0','p098-0','p085-0']},
{id:'snow',n:'04',en:'A blank page',pt:'Uma folha em branco',labelEn:'SNOW, SEEN FROM BAHIA',labelPt:'A NEVE, VISTA DA BAHIA',bodyEn:'It never snows in Bahia, where I come from. Snow erases the world and draws it again. Night in reverse. Darkness that lights up. A new chance.',bodyPt:'Na Bahia, de onde eu vim, não neva. A neve apaga o mundo e desenha de novo. Noite ao contrário. Escuridão que acende. Uma nova chance.',quoteEn:'All the world’s drawings.<br>A blank sheet of paper again.',quotePt:'Todos os desenhos do mundo.<br>De novo, uma folha em branco.',photos:['p149-0','p135-0','p148-0']},
{id:'water',n:'05',en:'Another world',pt:'Um outro mundo',labelEn:'ON EITHER SIDE OF THE SURFACE',labelPt:'DOS DOIS LADOS DA SUPERFÍCIE',bodyEn:'As a boy, I kept my eyes open underwater until they turned red. My first diving goggles changed everything. Water became a lens: bending light, distorting the familiar. It still feels like magic.',bodyPt:'Quando menino, abria os olhos debaixo d’água até ficarem vermelhos. O primeiro óculos de mergulho mudou tudo. A água virou lente: dobra a luz, distorce o familiar. Ainda parece mágica.',quoteEn:'Just an inch of air.<br>A whole new way of seeing.',quotePt:'Poucos centímetros de ar.<br>Um mundo inteiro para ver.',photos:['p169-0','p155-0','p165-0']},
{id:'memory',n:'06',en:'What stays',pt:'O que fica',labelEn:'PHOTOGRAPHY & MEMORY',labelPt:'FOTOGRAFIA E MEMÓRIA',bodyEn:'I suspect we remember very little. Mostly what we see in photographs. 1/125 of a second, kept for a lifetime. Perhaps that’s why I photograph what is about to go.',bodyPt:'Acho que a gente não lembra de quase nada. Só do que vê nas fotos. 1/125 de segundo, guardado para sempre. Talvez por isso eu fotografe o que está prestes a ir embora.',quoteEn:'My mother taught me<br>to give photographs a life.',quotePt:'Minha mãe me ensinou<br>a dar uso à fotografia.',photos:['p230-0','p223-0','p239-0']}
];
let language=new URLSearchParams(location.search).get('lang');
if(!['en','pt'].includes(language)){try{language=localStorage.getItem('olhar-language')}catch{}if(!['en','pt'].includes(language))language=navigator.language.startsWith('pt')?'pt':'en'}
let photos=[],activeFilter='all',visibleCount=32,viewerPhotos=[],viewerIndex=0,lastFocus;
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const dialog=$('#lightbox');const motion=matchMedia('(prefers-reduced-motion: reduce)');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=(p,small=false)=>`assets/${p.id}${small?'-small':''}.webp`;
function figure(p,small=false){return `<figure class="reveal"><button class="photo-button" data-photo="${p.id}" aria-label="${copy[language].open}: ${safe(p[language])}"><img src="${asset(p,small)}" ${small?'':`srcset="${asset(p,true)} 560w, ${asset(p)} ${Math.min(2200,p.width)}w" sizes="(max-width: 600px) 88vw, 80vw"`} width="${p.width}" height="${p.height}" loading="lazy" decoding="async" alt="${safe(p[language])}${p.place?' — '+safe(p.place):''}"></button><figcaption class="caption">${safe(p[language])}<span>${safe(p.place)}</span></figcaption></figure>`}
function renderChapters(){const key=language==='pt'?'Pt':'En';$('#chapters').innerHTML=chapters.map(c=>`<section class="chapter" id="${c.id}" data-chapter="${c.id}"><div class="chapter-head reveal"><p class="chapter-number">${c.n}<span>${c['label'+key]}</span></p><div><h2>${c[language]}</h2><p class="chapter-text">${c['body'+key]}</p></div></div><div class="feature-wide">${figure(photos.find(p=>p.id===c.photos[0]))}</div><div class="photo-pair">${c.photos.slice(1).map(id=>figure(photos.find(p=>p.id===id))).join('')}</div><p class="chapter-quote reveal">${c['quote'+key]}</p><button class="chapter-link" data-collection="${c.id}">${copy[language].view} ↗</button></section>`).join('')}
function renderFilters(){$('.filters').innerHTML=[{id:'all',name:copy[language].all},...chapters.map(c=>({id:c.id,name:c[language].replace(/\.$/,'')}))].map(c=>`<button data-filter="${c.id}" aria-pressed="${activeFilter===c.id}">${c.name}</button>`).join('')}
function filtered(){return activeFilter==='all'?photos:photos.filter(p=>p.group===activeFilter)}
function renderGrid(){const selected=filtered();$('#photo-grid').innerHTML=selected.slice(0,visibleCount).map(p=>figure(p,true)).join('');$('.load-more').hidden=visibleCount>=selected.length;$('.load-more').style.display=visibleCount>=selected.length?'none':'';$('.archive-count').textContent=`${selected.length} ${copy[language].count}`;renderFilters();observeReveals()}
let observer;function observeReveals(){if(motion.matches)return;document.documentElement.classList.add('motion');if(!observer)observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');observer.unobserve(e.target)}}),{threshold:.04});$$('.reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('pending');observer.observe(el)}})}
function setLanguage(lang,initial=false){language=lang;document.documentElement.lang=lang==='pt'?'pt-BR':'en-US';$$('[data-i18n]').forEach(el=>el.innerHTML=copy[lang][el.dataset.i18n]);$$('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.lang===lang));$('.skip').textContent=copy[lang].skip;$('.wordmark span').textContent=lang==='pt'?'FOTOGRAFIA':'PHOTOGRAPHY';$('.hero-photo').alt=lang==='pt'?'Um barco ao luar nas águas de Penha, 2004':'A boat in the moonlight on the waters of Penha, 2004';$('.about-photo img').alt=lang==='pt'?'Marcelo Kertész fotografando a si mesmo no espelho':'Marcelo Kertész photographing himself in a mirror';$('.site-header nav').setAttribute('aria-label',lang==='pt'?'Navegação principal':'Main navigation');$('.filters').setAttribute('aria-label',lang==='pt'?'Coleção de fotografias':'Photo collection');dialog.setAttribute('aria-label',lang==='pt'?'Visualizador de fotografias':'Photograph viewer');[['.viewer-close','close'],['.viewer-prev','prev'],['.viewer-next','next']].forEach(([s,k])=>$(s).setAttribute('aria-label',copy[lang][k]));$('meta[name=description]').content=lang==='pt'?'Fotografias, memórias e um pouco de pretensão. Uma viagem pelo olhar de Marcelo Kertész.':'Photographs, memories, and a little pretension. A photographic journey by Marcelo Kertész.';$$('[data-i18n-alt]').forEach(el=>el.alt=copy[lang][el.dataset.i18nAlt]);if(photos.length){renderHero();renderChapters();renderGrid()}if(!initial){try{localStorage.setItem('olhar-language',lang)}catch{}const url=new URL(location);url.searchParams.set('lang',lang);history.replaceState(null,'',url)}}
function showPhoto(){const p=viewerPhotos[viewerIndex];$('.viewer-image').src=asset(p);$('.viewer-image').alt=p[language]+(p.place?' — '+p.place:'');$('.viewer-title').textContent=p[language];$('.viewer-place').textContent=p.place;$('.viewer-number').textContent=`${String(viewerIndex+1).padStart(2,'0')} / ${viewerPhotos.length}`;const next=viewerPhotos[(viewerIndex+1)%viewerPhotos.length];const preload=new Image();preload.src=asset(next)}
function openPhoto(id){lastFocus=document.activeElement;viewerPhotos=lastFocus.closest('#photo-grid')?filtered():photos;viewerIndex=viewerPhotos.findIndex(p=>p.id===id);showPhoto();dialog.showModal();document.body.classList.add('viewer-open');$('.viewer-close').focus()}
function movePhoto(step){viewerIndex=(viewerIndex+step+viewerPhotos.length)%viewerPhotos.length;showPhoto()}
function selectFilter(id){activeFilter=id;visibleCount=32;renderGrid()}
document.addEventListener('click',e=>{const lang=e.target.closest('[data-lang]');if(lang)setLanguage(lang.dataset.lang);const photo=e.target.closest('[data-photo]');if(photo)openPhoto(photo.dataset.photo);const filter=e.target.closest('[data-filter]');if(filter){const id=filter.dataset.filter;selectFilter(id);$(`[data-filter="${id}"]`).focus({preventScroll:true})}const collection=e.target.closest('[data-collection]');if(collection){selectFilter(collection.dataset.collection);$('#archive').scrollIntoView({behavior:motion.matches?'instant':'smooth'})}});
$('.load-more').addEventListener('click',()=>{const previous=visibleCount;visibleCount+=32;renderGrid();const next=$$('#photo-grid .photo-button')[previous];next?.focus({preventScroll:true})});$('.viewer-close').addEventListener('click',()=>dialog.close());$('.viewer-prev').addEventListener('click',()=>movePhoto(-1));$('.viewer-next').addEventListener('click',()=>movePhoto(1));dialog.addEventListener('close',()=>{document.body.classList.remove('viewer-open');lastFocus?.focus({preventScroll:true})});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();movePhoto(-1)}if(e.key==='ArrowRight'){e.preventDefault();movePhoto(1)}});let touchStart;dialog.addEventListener('touchstart',e=>{touchStart={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true});dialog.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)movePhoto(dx>0?-1:1);touchStart=null},{passive:true});
let ticking=false;function scrollMotion(){const y=scrollY,total=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=`${total?y/total*100:0}%`;if(!motion.matches&&y<innerHeight)$('.hero-photo').style.transform=`translateY(${y*.15}px) scale(1.025)`;ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollMotion);ticking=true}},{passive:true});motion.addEventListener('change',()=>{document.documentElement.classList.toggle('motion',!motion.matches);if(motion.matches){$('.hero-photo').style.transform='none';$$('.pending').forEach(e=>e.classList.remove('pending'))}});
$('.hero-prev').addEventListener('click',()=>moveHero(-1));$('.hero-next').addEventListener('click',()=>moveHero(1));
$('.hero-gallery-controls').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveHero(e.key==='ArrowLeft'?-1:1)}});
setLanguage(language,true);fetch('photos.json').then(r=>{if(!r.ok)throw Error('photos');return r.json()}).then(data=>{photos=data;setLanguage(language,true);if(location.hash){requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView())}}).catch(()=>{$('#chapters').innerHTML=`<p style="padding:40px 6%">${language==='pt'?'Não foi possível carregar as fotografias. Recarregue a página para tentar novamente.':'The photographs could not load. Please reload the page to try again.'}</p>`});
